{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_6f4a11182a7e1a94c6a83fb8", "claim_ids": ["claim_68d5cfb04eeea7d3f6d74ef7", "claim_dc5e20c617849c64e31f5fd9"], "query_ids": ["q_411"], "claims": [{"claim_id": "claim_68d5cfb04eeea7d3f6d74ef7", "quote": "At this time, products of Indonesia will be subject to an additional ad valorem rate of duty of 19 percent. At the time of entry, you must report the Chapter 99 heading applicable to your product classification, 9903.02.27, in addition to subheading 3824.99.3990, HTSUS, listed above.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=NY+N353878&highlight=3824.99.39%2A", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "Indonesia", "exporting_country": "Indonesia", "duty_rate": "19 percent", "effective_date": "April 5, 2025"}}, {"claim_id": "claim_dc5e20c617849c64e31f5fd9", "quote": "At this time, products of Turkey will be subject to an additional ad valorem rate of duty of 15 percent. At the time of entry, you must report the Chapter 99 heading applicable to your product classification, 9903.02.64, in addition to subheading 3824.99.3990, HTSUS, listed above.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=NY+N353878&highlight=3824.99.39%2A", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "Turkey", "exporting_country": "Turkey", "duty_rate": "15 percent", "effective_date": "April 5, 2025"}}]}, {"pair_id": "conflict_d90eacfea9301f240af008d3", "claim_ids": ["claim_18b4f161dc0712841fbbdc97", "claim_df41cf011479c23bdf0fbaa9"], "query_ids": ["q_412"], "claims": [{"claim_id": "claim_18b4f161dc0712841fbbdc97", "quote": "28332910 Cobalt sulfate", "url": "https://www.whitehouse.gov/wp-content/uploads/2025/04/Annex-II.pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Cobalt sulfate", "hts_code": "28332910"}}, {"claim_id": "claim_df41cf011479c23bdf0fbaa9", "quote": "| 28332910 | Cobalt sulfate |", "url": "https://www.presidency.ucsb.edu/documents/executive-order-14257-regulating-imports-with-reciprocal-tariff-rectify-trade-practices", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "Cobalt sulfate", "hts_code": "28332910"}}]}, {"pair_id": "conflict_cd26ebc22ffe18e59d5c9bd0", "claim_ids": ["claim_2ed15bf488a38f091af25b91", "claim_a6f4b345ecf0342b6544e519"], "query_ids": ["q_412"], "claims": [{"claim_id": "claim_2ed15bf488a38f091af25b91", "quote": "NAICS #325180 indicates this is a product of the Other Basic Inorganic Chemical Manufacturing industry.", "url": "https://www.shipnerd.com/support/freight-class/shipping-codes/chemical/inorganic-compound-precious-metal-rare-earth-radioactive-isotope/sulphates-alums-peroxosulphates-persulphates-062833/other-06283329/cobalt-sulfate-062833291000", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "ShipNerd", "hts_code": "2833.29.10.00", "duty_rate": "1.4%"}}, {"claim_id": "claim_a6f4b345ecf0342b6544e519", "quote": "The End Use code for Chemicals-inorganic is #12530. END USE may affect tariffs, duties, taxes, restrictions and other import/export considerations.", "url": "https://www.shipnerd.com/support/freight-class/shipping-codes/chemical/inorganic-compound-precious-metal-rare-earth-radioactive-isotope/sulphates-alums-peroxosulphates-persulphates-062833/other-06283329/cobalt-sulfate-062833291000", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "ShipNerd", "hts_code": "2833.29.10.00", "duty_rate": "1.4%"}}]}, {"pair_id": "conflict_065a5d76f0975117ea51f3ee", "claim_ids": ["claim_c8005fe64f160feb5e2dcd34", "claim_dfe3c7c897bd2b278694d32e"], "query_ids": ["q_412"], "claims": [{"claim_id": "claim_c8005fe64f160feb5e2dcd34", "quote": "Special Rate of Duty: | Free (A, AU, BH, CL, CO, D, E, IL, JO, KR, MA, OM, P, PA, PE, S, SG) |", "url": "https://www.shipnerd.com/support/freight-class/shipping-codes/chemical/inorganic-compound-precious-metal-rare-earth-radioactive-isotope/sulphates-alums-peroxosulphates-persulphates-062833/other-06283329/cobalt-sulfate-062833291000", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "ShipNerd", "hts_code": "2833.29.10.00", "duty_rate": "Free"}}, {"claim_id": "claim_dfe3c7c897bd2b278694d32e", "quote": "Column 2 Rate of Duty: | 6.5% |", "url": "https://www.shipnerd.com/support/freight-class/shipping-codes/chemical/inorganic-compound-precious-metal-rare-earth-radioactive-isotope/sulphates-alums-peroxosulphates-persulphates-062833/other-06283329/cobalt-sulfate-062833291000", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "ShipNerd", "hts_code": "2833.29.10.00", "duty_rate": "6.5%"}}]}, {"pair_id": "conflict_7487d92f9b3a6192f4fd642f", "claim_ids": ["claim_123212bf9d5bcd421c23b053", "claim_7fa882420ecdd1e4316be013"], "query_ids": ["q_413"], "claims": [{"claim_id": "claim_123212bf9d5bcd421c23b053", "quote": "The general rate of duty will be 0.1 percent ad valorem.", "url": "https://rulings.cbp.gov/ruling/N299059", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "0.1 percent"}}, {"claim_id": "claim_7fa882420ecdd1e4316be013", "quote": "The general rate of duty will be 0.1 percent ad valorem.", "url": "https://rulings.cbp.gov/ruling/N288463", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "0.1 percent"}}]}, {"pair_id": "conflict_ac4c6e24db0a6a2befb74f59", "claim_ids": ["claim_35c884fb88fb886fe82ce774", "claim_58ddf5b0ef8f3afc6130f7b6"], "query_ids": ["q_413"], "claims": [{"claim_id": "claim_35c884fb88fb886fe82ce774", "quote": "The bill’s signing will affect cobalt products listed under HS code 8105.20.30, which the Harmonized Tariff Schedule (HTS) defines as cobalt mattes and other intermediate products of cobalt metallurgy; unwrought cobalt; powders; and unwrought cobalt: alloys.", "url": "https://www.fastmarkets.com/insights/us-imports-of-russian-cobalt-to-face-45-duty", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "cobalt products listed under HS code 8105.20.30", "hts_code": "8105.20.30", "duty_rate": "45%"}}, {"claim_id": "claim_58ddf5b0ef8f3afc6130f7b6", "quote": "The higher duty rate for these products is listed as 45% in HTS/Rate 2, up from 4.4.% under General/Rate 1 regime.", "url": "https://www.fastmarkets.com/insights/us-imports-of-russian-cobalt-to-face-45-duty", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "45%"}}]}, {"pair_id": "conflict_14333f1c8a5f56ca2b42fde5", "claim_ids": ["claim_062f0f430af992bac4adbf6e", "claim_e38a3dcfc47c76f180432435"], "query_ids": ["q_415"], "claims": [{"claim_id": "claim_062f0f430af992bac4adbf6e", "quote": "On January 14th 2026, President Trump released a proclamation announcing that there will be no immediate tariffs or quotas on critical minerals and the U.S. will enter into negotiations with trading partners to adjust their imports.", "url": "https://www.strtrade.com/trade-news-resources/tariff-actions-resources/section-232-investigation-critical-minerals", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "no immediate tariffs or quotas", "announcement_date": "January 14th 2026", "reported_policy_status": "no immediate tariffs or quotas on critical minerals"}}, {"claim_id": "claim_e38a3dcfc47c76f180432435", "quote": "Other actions may be taken within 180 days of January 14, 2026, if agreements are not reached, are not being carried out, or are ineffective.", "url": "https://www.strtrade.com/trade-news-resources/tariff-actions-resources/section-232-investigation-critical-minerals", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"expiration_date": "within 180 days of January 14, 2026"}}]}, {"pair_id": "conflict_cacc7ab99898dbdd84ebddbc", "claim_ids": ["claim_14536d3846b85cc1ddd5ec4c", "claim_6d47a824fd7ea2cf7b1bf9c2"], "query_ids": ["q_415"], "claims": [{"claim_id": "claim_14536d3846b85cc1ddd5ec4c", "quote": "Despite broad trade enforcement measures enacted by the U.S. government in early 2025—including reciprocal tariffs and national security-related duties—rare earth compounds under HS 284690 were explicitly exempted from additional ad valorem tariffs.", "url": "https://gtaic.ai/market-reports/us-rare-earth-compound-imports-2024", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "additional ad valorem tariffs", "legal_authority": "U.S. government in early 2025", "affected_product": "rare earth compounds under HS 284690"}}, {"claim_id": "claim_6d47a824fd7ea2cf7b1bf9c2", "quote": "U.S. Executive Orders in 2025 exempted HS 284690 from new tariffs, reflecting its role as a critical input in national security and technology sectors.", "url": "https://gtaic.ai/market-reports/us-rare-earth-compound-imports-2024", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "new tariffs", "legal_authority": "U.S. Executive Orders in 2025", "affected_product": "HS 284690", "effective_date": "February to April 2025"}}]}, {"pair_id": "conflict_ab1e9a3a48b3b9677e096b32", "claim_ids": ["claim_4f51f42c7bd0a459852eba90", "claim_c116cca96834c9c84a8cc201"], "query_ids": ["q_417"], "claims": [{"claim_id": "claim_4f51f42c7bd0a459852eba90", "quote": "After the U.S. dropped tariffs on Chinese goods from 145% to 30%, and China slashed tariffs from 125% to 10%, this suspension followed as a goodwill gesture.", "url": "https://www.facebook.com/unboxfactory/posts/china-lifts-rare-earth-export-ban-for-28-us-companies-after-major-trade-breakthr/738108945206825", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "U.S. dropped tariffs on Chinese goods from 145% to 30%", "duty_rate": "30%"}}, {"claim_id": "claim_c116cca96834c9c84a8cc201", "quote": "After the U.S. dropped tariffs on Chinese goods from 145% to 30%, and China slashed tariffs from 125% to 10%, this suspension followed as a goodwill gesture.", "url": "https://www.facebook.com/unboxfactory/posts/china-lifts-rare-earth-export-ban-for-28-us-companies-after-major-trade-breakthr/738108945206825", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "China slashed tariffs from 125% to 10%", "duty_rate": "10%"}}]}, {"pair_id": "conflict_f57a58c8bb0d975022ed2e44", "claim_ids": ["claim_9ad8cb313cf611085a4fee39", "claim_be2f90159e062f18fdbf061a"], "query_ids": ["q_417"], "claims": [{"claim_id": "claim_9ad8cb313cf611085a4fee39", "quote": "On April 4, 2024, China responded to U.S. tariffs, which at the time were 145% on certain imports, and up to 245% on other products, by placing export restrictions on seven REEs – samarium, gadolinium, terbium, dysprosium, lutetium, scandium, and yttrium", "url": "https://pamirllc.com/blog/china-and-the-us-sign-a-deal-to-accelerate-the-import-of-rare-earth-elements-rees", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"announcement_date": "April 4, 2024"}}, {"claim_id": "claim_be2f90159e062f18fdbf061a", "quote": "On April 4, 2024, China responded to U.S. tariffs, which at the time were 145% on certain imports, and up to 245% on other products, by placing export restrictions on seven REEs – samarium, gadolinium, terbium, dysprosium, lutetium, scandium, and yttrium", "url": "https://pamirllc.com/blog/china-and-the-us-sign-a-deal-to-accelerate-the-import-of-rare-earth-elements-rees", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"exporting_country": "China", "duty_rate": "145%"}}]}]}

